from __future__ import annotations

from datetime import date, datetime, time
import re
from typing import Optional, Any


def parse_flexible_date(value: str | datetime | date | None) -> Optional[datetime]:
    """
    Parse flexible date inputs and return datetime.
    Canonical output across the API should be YYYY/MM/DD; legacy day-first
    inputs are still accepted for backward compatibility during migration.
    Accepted:
    - YYYY/MM/DD, YYYY-MM-DD, YYYY.MM.DD
    - DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY
    - YYYYMMDD, DDMMYYYY
    - ISO datetime/date strings
    """
    if value is None:
        return None
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime(value.year, value.month, value.day)

    raw = str(value).strip()
    if not raw:
        return None

    for fmt in (
        "%Y/%m/%d",
        "%Y-%m-%d",
        "%Y.%m.%d",
        "%d/%m/%Y",
        "%d-%m-%Y",
        "%d.%m.%Y",
        "%d/%m/%y",
        "%d-%m-%y",
        "%d.%m.%y",
        "%y/%m/%d",
        "%Y%m%d",
        "%d%m%Y",
        "%d%m%y",
    ):
        try:
            return datetime.strptime(raw, fmt)
        except ValueError:
            pass

    digits = re.sub(r"\D", "", raw)
    if len(digits) == 8:
        yyyy, mm, dd = digits[:4], digits[4:6], digits[6:8]
        try:
            return datetime(int(yyyy), int(mm), int(dd))
        except ValueError:
            pass
        dd, mm, yyyy = digits[:2], digits[2:4], digits[4:8]
        try:
            return datetime(int(yyyy), int(mm), int(dd))
        except ValueError:
            pass

    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        return None


def normalize_date_ymd(value: str | datetime | date | None, include_time: bool = False) -> Optional[str]:
    """
    Normalize date to YYYY/MM/DD format. If include_time is True and time is present,
    return YYYY/MM/DD HH:MM:SS format.
    """
    dt = parse_flexible_date(value)
    if not dt:
        return None
    if include_time and dt.time() != time(0, 0, 0):
        return dt.strftime("%Y/%m/%d %H:%M:%S")
    return dt.strftime("%Y/%m/%d")


def normalize_time_str(value: Any) -> str:
    """
    Normaliza valores de hora provenientes de Excel o inputs manuales a formato HH:MM:SS (o HH:MM).
    Maneja fracciones decimales de día de Excel (ej. 0.4166666666666667 -> 10:00:00) y objetos time/datetime.
    Garantiza que la salida nunca exceda 10 caracteres para respetar el límite VARCHAR(10) de base de datos.
    """
    if value is None:
        return ""
    if isinstance(value, (datetime, time)):
        return value.strftime("%H:%M:%S")
    if isinstance(value, (int, float)):
        try:
            f = float(value)
            if 0.0 <= f < 1.0:
                total_seconds = int(round(f * 86400)) % 86400
                h = total_seconds // 3600
                m = (total_seconds % 3600) // 60
                s = total_seconds % 60
                return f"{h:02d}:{m:02d}:{s:02d}"
        except Exception:
            pass
        return str(value).strip()[:10]

    raw = str(value).strip()
    if not raw:
        return ""

    if re.match(r"^0\.\d+$", raw):
        try:
            f = float(raw)
            if 0.0 <= f < 1.0:
                total_seconds = int(round(f * 86400)) % 86400
                h = total_seconds // 3600
                m = (total_seconds % 3600) // 60
                s = total_seconds % 60
                return f"{h:02d}:{m:02d}:{s:02d}"
        except Exception:
            pass

    for fmt in ("%H:%M:%S", "%H:%M", "%I:%M:%S %p", "%I:%M %p", "%I:%M:%S%p", "%I:%M%p"):
        try:
            dt = datetime.strptime(raw, fmt)
            return dt.strftime("%H:%M:%S")
        except ValueError:
            pass

    return raw[:10]
